INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47111, 'Jeremiah 30:11', 'Jeremiah', 30, 11, 'نو مالِک خُدائ فرمائى چې، زۀ ستا مل يم او زۀ به تا بچ کړم. او زۀ به هغه ټول قومونه مکمل تباه کړم چرته چې ما تاسو خوارۀ وارۀ کړى وئ، خو زۀ به تاسو په مکمل توګه نۀ تباه کوم. زۀ به تاسو په اِنصاف سره تنبيه کړم، او زۀ به تاسو هم داسې بې‌سزا نۀ پرېږدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_11.mp3', '', 1761754199, 1761754199),
(47112, 'Jeremiah 30:12', 'Jeremiah', 30, 12, 'مالِک خُدائ داسې فرمائى چې، ستاسو زخمونه خطرناک دى، او ستاسو زخمونه لاعلاجه دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_12.mp3', '', 1761754199, 1761754199),
(47113, 'Jeremiah 30:13', 'Jeremiah', 30, 13, 'داسې څوک نشته چې ستا خيال وساتى، ستا د زخمونو دپاره دارو نشته، ستا دپاره علاج نشته دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_13.mp3', '', 1761754199, 1761754199),
(47114, 'Jeremiah 30:14', 'Jeremiah', 30, 14, 'ستا ټولو ملګرو تۀ هېر کړے يې، هغوئ ستا پرواه نۀ کوى. ما په تا باندې داسې حمله وکړه لکه څنګه چې په دشمن کوم، او د يو ظالم په شان مې سزا درکړه، ځکه چې ستا شرارتونه ډېر غټ دى، او ستا ګناهونه ډېر زيات دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_14.mp3', '', 1761754199, 1761754199),
(47115, 'Jeremiah 30:15', 'Jeremiah', 30, 15, 'نو بيا ولې تاسو په خپلو زخمونو او درد ژړا فرياد کوئ، او تاسو وايئ چې د دې خو هيڅ علاج نشته؟ خو دا ما ستاسو د لويو شرارتونو او ډېرو ګناهونو په وجه درسره وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_15.mp3', '', 1761754199, 1761754199),
(47116, 'Jeremiah 30:16', 'Jeremiah', 30, 16, 'خو هر هغه څوک چې تاسو روغ تېروى هغوئ به روغ تېر کړے شى، او ستاسو ټول دشمنان به جلاوطن کړے شى. هر هغه څوک چې تاسو لوټ کوى هغوئ به لوټ کړے شى، او څوک چې په تاسو باندې حمله کوى په هغوئ باندې به حمله وکړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_16.mp3', '', 1761754199, 1761754199),
(47117, 'Jeremiah 30:17', 'Jeremiah', 30, 17, 'مالِک خُدائ فرمائى چې، زۀ به ستاسو صحت دوباره ښۀ کړم، او ستاسو زخمونو ته به شفا ورکړم. زۀ به دا کار وکړم ځکه چې ما اورېدلى دى چې خلق تا ته ”جلاوطن شوے“ وائى، ”صيون د چا چې څوک هم خيال نۀ ساتى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_17.mp3', '', 1761754199, 1761754199),
(47118, 'Jeremiah 30:18', 'Jeremiah', 30, 18, 'مالِک خُدائ فرمائى چې، زۀ به د يعقوب اولاد د غلامۍ نه واپس راولم او په هغوئ به رحم وکړم، د يروشلم تباه شوے ښار به هم هغه ځائ کښې دوباره آباد کړم، او زوړ محل به يې په خپل اصلى ځائ کښې ودروم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_18.mp3', '', 1761754199, 1761754199),
(47119, 'Jeremiah 30:19', 'Jeremiah', 30, 19, 'نو په هغه وخت کښې به د هغه خلقو نه د شُکر ګزارۍ حمدونه او د خوشحالۍ آوازونه واورېدلے شى. زۀ به د هغوئ شمېر زيات کړم، او هغوئ به کمولے نۀ شى. زۀ به خلق مجبور کړم چې د هغوئ عزت وکړى، او هغوئ به سپک نۀ شمېرلے کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_19.mp3', '', 1761754199, 1761754199),
(47120, 'Jeremiah 30:20', 'Jeremiah', 30, 20, 'د هغوئ ماشومان به لکه د پخوا په شان ژوند کوى، او د هغوئ جماعت به زما په مخکښې قائم شى، او زۀ به هغه ټولو خلقو له سزا ورکړم څوک چې په دوئ باندې ظلم کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_20.mp3', '', 1761754199, 1761754199),
(47121, 'Jeremiah 30:21', 'Jeremiah', 30, 21, 'د هغوئ مشر به د هغوئ د خپل قوم نه وى، او د هغوئ مشر به د هغوئ د خپلو خلقو نه وى. زۀ به هغه خپل ځان ته نزدې کړم او هغه به ما له راشى، ځکه چې څوک دا جرأت کولے شى چې نابللے راشى؟ دا د مالِک خُدائ فرمان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_21.mp3', '', 1761754199, 1761754199),
(47122, 'Jeremiah 30:22', 'Jeremiah', 30, 22, 'نو هغه وخت به تاسو زما خلق يئ او زۀ به ستاسو خُدائ پاک يم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_22.mp3', '', 1761754199, 1761754199),
(47123, 'Jeremiah 30:23', 'Jeremiah', 30, 23, 'ګورئ د مالِک خُدائ غصه لکه د طوفان په شان رانازليږى، او د تېزو هواګانو په شان د بدعمله خلقو په سر په غضب سره لګيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_23.mp3', '', 1761754199, 1761754199),
(47124, 'Jeremiah 30:24', 'Jeremiah', 30, 24, 'او د مالِک خُدائ سخت قهر او غضب به تر هغې پورې وى او واپس به نۀ شى ترڅو چې د هغۀ مقصد پوره شوے نۀ وى. په راتلونکو ورځو کښې به تاسو په دې هر څۀ باندې پوهه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah30_verse_24.mp3', '', 1761754199, 1761754199),
(47125, 'Deuteronomy 12:1', 'Deuteronomy', 12, 1, 'کله چې تاسو هغې خاورې ته ورننوځئ چې ستاسو د نیکونو څښتن خدای تاسو ته درکړې ده، نو ترڅو پورې چې ژوندي یئ په دې قوانینو باندې باید عمل وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_1.mp3', '', 1761754199, 1761754199),
(47126, 'Deuteronomy 12:2', 'Deuteronomy', 12, 2, 'خو هغه قومونه چې هلته اوسیږي د نورو خدایانو عبادت کوي. نو کله چې تاسو هغه خاوره ونیوله باید د هغوی د عبادت ځایونه په پوره توګه وران کړئ یعنې هغه ځایونه چې په غرونو او په غونډیو باندې دي او یا د شنو ونو لاندې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_2.mp3', '', 1761754199, 1761754199),
(47127, 'Deuteronomy 12:3', 'Deuteronomy', 12, 3, 'د هغوی د قربانۍ ځایونه راوغورځوئ او هغه لویې تیږې چې د هغوی د عبادت دپاره ورڅخه کار اخیستل کیږي، ټوټې ټوټې کړئ. د هغوی د اشیره بتان وسوځوئ او نور بتان یې راچپه کړئ، ترڅو بیا هېڅکله په هغو ځایونو کې د هغو بتانو عبادت ونه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_3.mp3', '', 1761754199, 1761754199),
(47128, 'Deuteronomy 12:4', 'Deuteronomy', 12, 4, 'د خپل څښتن خدای عبادت په داسې ډول مه کوئ لکه څنګه چې دا خلک د خپلو خدایانو عبادت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_4.mp3', '', 1761754199, 1761754199),
(47129, 'Deuteronomy 12:5', 'Deuteronomy', 12, 5, 'ستاسو د ټولو قبیلو د سیمو څخه به څښتن یو ځای غوره کړي او هلته باید تاسو د هغه حضور ته راشئ او د هغه عبادت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_5.mp3', '', 1761754199, 1761754199),
(47130, 'Deuteronomy 12:6', 'Deuteronomy', 12, 6, 'تاسو باید هلته خپلې سوځېدونکې نذرانې او نورې قربانۍ، خپل عشرونه او هدیې، هغه سوغاتونه چې د نذر په توګه یې څښتن ته ورکوئ، د خپلې خوښې نذرانې او د خپلو پادو او رمو لومړني زېږېدلي بچیان وړاندې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_6.mp3', '', 1761754199, 1761754199),
(47131, 'Deuteronomy 12:7', 'Deuteronomy', 12, 7, 'تاسو او ستاسو کورنۍ او نوکران به هلته د خپل څښتن خدای په حضور کې چې برکت یې درکړی دی خوراک کوئ او د هغو ښو شیانو دپاره به خوشحالي کوئ چې تاسو د هغو دپاره کار کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_7.mp3', '', 1761754199, 1761754199),
(47132, 'Deuteronomy 12:8', 'Deuteronomy', 12, 8, 'په هغې خاوره کې چې تاسو یې نیسئ، باید داسې کارونه ونه کړئ لکه څنګه چې دلته یې کوئ. تر اوسه پورې تاسو ټول د خپلې خوښې له مخې عبادت کوئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_8.mp3', '', 1761754199, 1761754199),
(47133, 'Deuteronomy 12:9', 'Deuteronomy', 12, 9, 'ځکه چې تاسو لا تر اوسه هغې خاورې ته چې ستاسو څښتن خدای یې درکوي او تاسو په کې په سوله کې ژوند کولای شئ، نه یئ ننوتلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_9.mp3', '', 1761754199, 1761754199),
(47134, 'Deuteronomy 12:10', 'Deuteronomy', 12, 10, 'کله چې تاسو د اردن د سیند څخه تېر شئ، څښتن به تاسو پرېږدي چې هغه خاوره ونیسئ او هلته واوسېږئ. هغه به تاسو د خپلو ټولو دښمنانو څخه په امن کې وساتي او په سوله کې به ژوند کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_10.mp3', '', 1761754199, 1761754199),
(47135, 'Deuteronomy 12:11', 'Deuteronomy', 12, 11, 'څښتن به د خپل عبادت دپاره یوازې یو ځای غوره کړي او تاسو باید هلته هغه ته هر هغه شی چې ما یې امر کړی دی راوړئ یعنې ستاسو سوځېدونکې نذرانې او نورې قربانۍ، عشرونه او هدیې او هغه ځانګړي سوغاتونه چې د نذر په توګه یې څښتن ته ورکوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_11.mp3', '', 1761754199, 1761754199),
(47136, 'Deuteronomy 12:12', 'Deuteronomy', 12, 12, 'هلته د هغه په حضور کې د خپلو اولادونو، نوکرانو او د هغو لاویانو سره خوشحالي کوئ چې ستاسو په ښارونو کې اوسیږي. په یاد لرئ چې لاویان به هېڅ خپله ځمکه ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_12.mp3', '', 1761754199, 1761754199),
(47137, 'Deuteronomy 12:13', 'Deuteronomy', 12, 13, 'په هرځای کې چې ستاسو خوښه وي باید هلته خپلې قربانۍ وړاندې نه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_13.mp3', '', 1761754199, 1761754199),
(47138, 'Deuteronomy 12:14', 'Deuteronomy', 12, 14, 'تاسو باید یوازې په یو ځای کې هغه قربانۍ وړاندې کړئ یعنې هغه ځای چې څښتن به یې ستاسو د قبیلو څخه په یوې قبیلې کې غوره کړي. تاسو باید یوازې په هغه ځای کې خپلې سوځېدونکې نذرانې وړاندې کړئ او هغه ټول کارونه وکړئ چې ما یې درته امر کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_14.mp3', '', 1761754199, 1761754199),
(47139, 'Deuteronomy 12:15', 'Deuteronomy', 12, 15, 'خو تاسو په ازادانه ډول کولای شئ چېرته چې اوسېږئ هلته حیوانات حلال کړئ او ویې خورئ. څومره چې څښتن درکوي هغه وخورئ. تاسو ټول که په مذهبي لحاظ پاک یئ یا ناپاک کولای شئ چې هغه داسې وخورئ لکه څنګه چې د هوسۍ یا د غرڅه غوښه خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_15.mp3', '', 1761754199, 1761754199),
(47140, 'Deuteronomy 12:16', 'Deuteronomy', 12, 16, 'خو د هغوی وینه باید ونه خورئ، تاسو باید هغه د اوبو په شان په ځمکه باندې توی کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_16.mp3', '', 1761754199, 1761754199),
(47141, 'Deuteronomy 12:17', 'Deuteronomy', 12, 17, 'هېڅ شی چې تاسو یې څښتن ته وړاندې کوئ باید ستاسو د اوسېدلو په ځایونو کې ونه خوړل شي، یعنې ستاسو د غلو دانو عشر، د شرابو یا د زیتونو د تېلو عشر، د پادو او رمو لومړني زېږېدلي بچیان، هغه سوغاتونه چې څښتن ته یې د نذر په توګه ورکوئ، د خپلې خوښې یا داسې نورې نذرانې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_17.mp3', '', 1761754199, 1761754199),
(47142, 'Deuteronomy 12:18', 'Deuteronomy', 12, 18, 'تاسو او ستاسو اولادونه دې ستاسو د نوکرانو او هغو لاویانو سره چې ستاسو په ښارونو کې اوسیږي دا نذرانې یوازې د خپل څښتن خدای په حضور کې یعنې د عبادت په هغه ځای کې وخورئ چې د هغه له خوا غوره کړای شوی دی. په هر کار کې چې کوئ یې د هغه په حضور کې خوشحالي وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_18.mp3', '', 1761754199, 1761754199),
(47143, 'Deuteronomy 12:19', 'Deuteronomy', 12, 19, 'ترڅو پورې چې تاسو په خپله خاوره کې اوسېږئ، پام کوئ چې لاویان هېر نه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_19.mp3', '', 1761754199, 1761754199),
(47144, 'Deuteronomy 12:20', 'Deuteronomy', 12, 20, 'کله چې ستاسو څښتن خدای د خپلې وعدې سره سم ستاسو سیمه پراخه کړي، هر وخت چې هرڅومره غوښه وغواړئ تاسو یې خوړلی شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_20.mp3', '', 1761754199, 1761754199),
(47145, 'Deuteronomy 12:21', 'Deuteronomy', 12, 21, 'که چېرې د عبادت ځای ستاسو څخه لېرې وي، نو لکه څنګه چې مې درته ویلي دي تاسو کولای شئ چې د خپلې پادې یا رمې یو حیوان چې څښتن درکړی وي حلال کړئ او غوښه یې په خپلو کورونو کې وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_21.mp3', '', 1761754199, 1761754199),
(47146, 'Deuteronomy 12:22', 'Deuteronomy', 12, 22, 'هرڅوک که په مذهبي لحاظ پاک وي یا ناپاک، کولای شي چې هغه غوښه داسې وخوري لکه څنګه چې د هوسۍ یا د غرڅه غوښه خوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_22.mp3', '', 1761754199, 1761754199),
(47147, 'Deuteronomy 12:25', 'Deuteronomy', 12, 25, 'که چېرې تاسو د دې امر اطاعت وکړئ، دا به د څښتن په نظر سم کار وي او ستاسو او ستاسو د اولادې هر کار به سم شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_25.mp3', '', 1761754199, 1761754199),
(47148, 'Deuteronomy 12:26', 'Deuteronomy', 12, 26, 'هغه نذرانې او سوغاتونه چې څښتن ته یې د نذر په توګه ورکوئ، هغه ځای ته یوسئ چې څښتن یې د خپل عبادت دپاره غوره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_26.mp3', '', 1761754199, 1761754199),
(47149, 'Deuteronomy 12:27', 'Deuteronomy', 12, 27, 'هلته هغه قربانۍ چې د څښتن د قربانۍ په ځای باندې په پوره توګه سوځول کیږي وړاندې کړئ. همدارنګه هغه قربانۍ هم وړاندې کړئ چې غوښه یې خورئ او وینه یې د قربانۍ په ځای باندې تویوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_27.mp3', '', 1761754199, 1761754199),
(47150, 'Deuteronomy 12:28', 'Deuteronomy', 12, 28, 'په وفادارۍ سره د دغو ټولو شیانو چې ما درته امر کړی دی اطاعت کوئ، نو ستاسو او ستاسو د اولادې هر کار به د تل دپاره سم وي، ځکه چې تاسو به هغه کارونه کوئ چې ستاسو د څښتن خدای په نظر کې نېک او سم وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_28.mp3', '', 1761754199, 1761754199),
(47151, 'Deuteronomy 12:29', 'Deuteronomy', 12, 29, 'څنګه چې تاسو د هغوی په خاوره باندې حمله وکړئ، نو ستاسو څښتن خدای به هغه قومونه تباه کړي او تاسو به هغه ځای ونیسئ او په کې به اوسېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_29.mp3', '', 1761754199, 1761754199),
(47152, 'Deuteronomy 12:30', 'Deuteronomy', 12, 30, 'کله چې څښتن هغه قومونه تباه کړل، پام کوئ چې د هغوی د مذهبي رواجونو څخه پیروي ونه کړئ، ځکه چې دا به ستاسو دپاره یو وژونکی دام وي. د دې خبرې د معلومولو هڅه مه کوئ چې هغوی په کوم ډول د خپلو خدایانو عبادت کوي، د دې دپاره چې تاسو هم همدا ډول عبادت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_30.mp3', '', 1761754199, 1761754199),
(47153, 'Deuteronomy 12:31', 'Deuteronomy', 12, 31, 'د خپل څښتن خدای عبادت په هغه ډول مه کوئ لکه څنګه چې هغوی د خپلو خدایانو عبادت کوي، ځکه چې هغوی په خپل عبادت کې ټول هغه ناوړه کارونه کوي چې څښتن ورڅخه کرکه کوي. هغوی حتی د قربانۍ په ځایونو باندې خپل اولادونه هم په اور کې قرباني کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_31.mp3', '', 1761754199, 1761754199),
(47154, 'Deuteronomy 12:32', 'Deuteronomy', 12, 32, 'ما چې کوم حکمونه تاسو ته درکړي دي په هغو باندې عمل کوئ. د هغو څخه مه څه کموئ او مه یې ورزیاتوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy12_verse_32.mp3', '', 1761754199, 1761754199),
(47155, 'Leviticus 4:1', 'Leviticus', 4, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_1.mp3', '', 1761754199, 1761754199),
(47156, 'Leviticus 4:2', 'Leviticus', 4, 2, '«اسراییلیانو ته ووایه: کله چې څوک ګناه کوي او په سهوې سره د څښتن حکمونه ماتوي، هغه باید دا لاندېني اصول مراعت کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_2.mp3', '', 1761754199, 1761754199),
(47157, 'Leviticus 4:3', 'Leviticus', 4, 3, 'که چېرې لوی کاهن ګناه وکړي او په دې ډول قوم ګناهکار کړي، هغه به یو داسې خوسی وړاندې کوي چې کوم عیب په کې نه وي او د خپلې ګناه دپاره به یې څښتن ته قرباني کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_3.mp3', '', 1761754199, 1761754199),
(47158, 'Leviticus 4:4', 'Leviticus', 4, 4, 'هغه دې خوسی د سپېڅلې خېمې د دروازې خولې ته راولي، خپل لاس دې د هغه په سر باندې کېږدي او د څښتن په حضور کې دې هلته حلال کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_4.mp3', '', 1761754199, 1761754199),
(47159, 'Leviticus 4:5', 'Leviticus', 4, 5, 'بیا به لوی کاهن د خوسي د وینې څخه لږه وینه واخلي او دننه خېمې ته به یې یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_5.mp3', '', 1761754199, 1761754199),
(47160, 'Leviticus 4:6', 'Leviticus', 4, 6, 'هغه دې خپله ګوته په وینه کې غوټه کړي او لږه وینه دې واخلي او اووه ځلې دې د څښتن په حضور کې د سپېڅلي ځای د پردې مخې ته وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_6.mp3', '', 1761754199, 1761754199),
(47161, 'Leviticus 4:7', 'Leviticus', 4, 7, 'بیا به کاهن لږه وینه په خېمه کې د خوشبویۍ د قربانۍ د ځای په ښکرونو باندې وسولوي. هغه به پاتې وینه د خېمې د دروازې په خوله کې د سوځېدونکې نذرانې د قربانۍ د ځای په بېخ کې تویه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_7.mp3', '', 1761754199, 1761754199),
(47162, 'Leviticus 4:8', 'Leviticus', 4, 8, 'هغه به د دې خوسي څخه ټوله وازګه واخلي، یعنې هغه وازګه چې په کولمو باندې پرته وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_8.mp3', '', 1761754199, 1761754199),
(47163, 'Leviticus 4:9', 'Leviticus', 4, 9, 'پښتورګي د هغې وازګې سره چې دپاسه ورباندې پرته وي او د اینې ډېره ښه برخه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_9.mp3', '', 1761754199, 1761754199),
(47164, 'Leviticus 4:10', 'Leviticus', 4, 10, 'لکه څنګه چې وازګه د خوسي څخه چې د سلامتۍ د نذرانې په توګه قرباني کیږي، لېرې کیږي. بیا به کاهن هغه سوځېدونکې نذرانې د قربانۍ په ځای باندې وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_10.mp3', '', 1761754199, 1761754199),
(47165, 'Leviticus 4:11', 'Leviticus', 4, 11, 'خو هغه به د هغه پوستکی، ټوله غوښه، سر، پښې او د هغه د نس دنننۍ برخې د خوشایو سره واخلي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_11.mp3', '', 1761754199, 1761754199),
(47166, 'Leviticus 4:12', 'Leviticus', 4, 12, 'هغه به ټول د کمپ څخه دباندې پاک ځای ته چېرته چې ایرې غورځول کیږي یوسي او هلته به یې د لرګیو په اور باندې وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_12.mp3', '', 1761754199, 1761754199),
(47167, 'Leviticus 4:13', 'Leviticus', 4, 13, 'که چېرې د اسراییلو ټول قوم په سهوې سره ګناه وکړي او د څښتن د حکمونو څخه کوم حکم مات کړي، نو هغوی به ګناهکار وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_13.mp3', '', 1761754199, 1761754199),
(47168, 'Leviticus 4:14', 'Leviticus', 4, 14, 'کله چې هغوی په خپله ګناه پوه شي، باید د ګناه د نذرانې په توګه یو خوسی راولي او د سپېڅلې خېمې په مخکې دې هغه وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_14.mp3', '', 1761754199, 1761754199),
(47169, 'Leviticus 4:15', 'Leviticus', 4, 15, 'د قوم مشران دې خپل لاسونه د خوسي په سر باندې کېږدي او خوسی دې د څښتن په حضور کې حلال شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_15.mp3', '', 1761754199, 1761754199),
