(47171, 'Leviticus 4:17', 'Leviticus', 4, 17, 'هغه دې خپله ګوته په وینه کې غوټه کړي او هغه دې د څښتن په حضور کې اووه ځلې د پردې مخې ته وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_17.mp3', '', 1761754199, 1761754199),
(47172, 'Leviticus 4:18', 'Leviticus', 4, 18, 'بیا دې لوی کاهن لږه وینه په سپېڅلې خېمه کې د څښتن په حضور کې د خوشبویۍ د قربانۍ د ځای په ښکرونو باندې وسولوي. هغه به پاتې وینه د سپېڅلې خېمې د دروازې په خوله کې د سوځېدونکې نذرانې د قربانۍ د ځای په بېخ کې تویه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_18.mp3', '', 1761754199, 1761754199),
(47173, 'Leviticus 4:19', 'Leviticus', 4, 19, 'بیا به هغه د خوسي ټوله وازګه لېرې کړي او د قربانۍ په ځای باندې به یې وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_19.mp3', '', 1761754199, 1761754199),
(47174, 'Leviticus 4:20', 'Leviticus', 4, 20, 'هغه به د دې خوسي سره هماغسې کار وکړي لکه څنګه چې د ګناه د نذرانې د خوسي سره یې کړی ؤ. په دې ډول به کاهن د قوم دپاره کفاره ادا کړي او هغوی به وبخښل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_20.mp3', '', 1761754199, 1761754199),
(47175, 'Leviticus 4:21', 'Leviticus', 4, 21, 'بیا به هغه خوسی د کمپ څخه دباندې یوسي او وبه یې سوځوي، لکه څنګه چې هغه خوسی یې سوځولی ؤ چې د هغوی د ګناه دپاره وړاندې شوی ؤ. دا هغه نذرانه ده چې د ټول قوم د ګناه د لېرې کولو دپاره ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_21.mp3', '', 1761754199, 1761754199),
(47176, 'Leviticus 4:22', 'Leviticus', 4, 22, 'کله چې یو مشر په سهوې سره ګناه وکړي او د څښتن د حکمونو څخه کوم حکم مات کړي، نو هغه به ګناهکار وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_22.mp3', '', 1761754199, 1761754199),
(47177, 'Leviticus 4:23', 'Leviticus', 4, 23, 'کله چې هغه د خپلې ګناه څخه خبر کړای شي، باید د خپلې نذرانې په توګه یو داسې سېرلی راولي چې کوم عیب په کې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_23.mp3', '', 1761754199, 1761754199),
(47178, 'Leviticus 4:24', 'Leviticus', 4, 24, 'هغه دې خپل لاس د سېرلي په سر باندې کېږدي او په هغه ځای کې دې حلال کړي چې د څښتن په حضور کې د سوځېدونکې نذرانې دپاره حیوانات حلالیږي. دا د ګناه نذرانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_24.mp3', '', 1761754199, 1761754199),
(47179, 'Leviticus 4:25', 'Leviticus', 4, 25, 'بیا دې کاهن د هغه سېرلی د وینې څخه په خپله ګوته باندې لږه وینه راواخلي او د قربانۍ د ځای په ښکرونو باندې دې وسولوي. پاتې وینه به د قربانۍ د ځای په بېخ کې تویه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_25.mp3', '', 1761754199, 1761754199),
(47180, 'Leviticus 4:26', 'Leviticus', 4, 26, 'بیا دې هغه دا ټوله وازګه د قربانۍ په ځای باندې وسوځوي لکه څنګه چې هغه د سلامتۍ د نذرانې وازګه وسوځوله. په دې ډول به کاهن د هغه مشر د ګناه دپاره کفاره ادا کړي او هغه به وبخښل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_26.mp3', '', 1761754199, 1761754199),
(47181, 'Leviticus 4:27', 'Leviticus', 4, 27, 'که چېرې کوم عادي کس په سهوې سره ګناه وکړي او د څښتن د حکمونو څخه کوم حکم مات کړي، نو هغه به ګناهکار وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_27.mp3', '', 1761754199, 1761754199),
