(47188, 'Leviticus 4:34', 'Leviticus', 4, 34, 'بیا دې کاهن په خپله ګوته باندې د هغه حیوان لږه وینه راواخلي او د قربانۍ د ځای په ښکرونو باندې دې وسولوي او پاتې وینه دې د قربانۍ د ځای په بېخ کې تویه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_34.mp3', '', 1761754199, 1761754199),
(47189, 'Leviticus 4:35', 'Leviticus', 4, 35, 'بیا به د هغې څخه ټوله وازګه لېرې کړي، لکه څنګه چې د سلامتۍ د نذرانې د پسه یا مېږې څخه لېرې کیږي او کاهن به هغه د قربانۍ په ځای باندې د هغو نذرانو سره یوځای وسوځوي چې څښتن ته تیاریږي. په دې ډول به کاهن د هغه کس د ګناه دپاره کفاره ادا کړي او هغه به وبخښل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus4_verse_35.mp3', '', 1761754199, 1761754199),
(47190, 'Deuteronomy 25:1', 'Deuteronomy', 25, 1, 'فرض کړئ دوه اسراییلیان محکمې ته ورځي چې یوه دعوه حل کړي او یو تن یې بې ګناه او بل یې مجرم وګڼل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_1.mp3', '', 1761754199, 1761754199),
(47191, 'Deuteronomy 25:2', 'Deuteronomy', 25, 2, 'که چېرې په مجرم باندې د وهلو حکم وشي، قاضي دې هغه پړمخې څملوي او په قمچینه باندې دې ووهي. د قمچینې د ګوزارونو شمېر به د هغه په جرم پورې اړه ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_2.mp3', '', 1761754199, 1761754199),
(47192, 'Deuteronomy 25:3', 'Deuteronomy', 25, 3, 'هغه به د څلوېښتو ګوزارونو څخه زیات نه وهل کیږي، د هغې څخه زیات به په عام محضر کې د هغه د سپکاوي سبب شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_3.mp3', '', 1761754199, 1761754199),
(47193, 'Deuteronomy 25:4', 'Deuteronomy', 25, 4, 'د غلو دانو د غوبل کولو په وخت کې د غویي خوله مه تړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_4.mp3', '', 1761754199, 1761754199),
(47194, 'Deuteronomy 25:5', 'Deuteronomy', 25, 5, 'که چېرې دوه ورونه په یو جایداد باندې ژوند کوي او د هغو څخه یو تن مړ شي او هېڅ زوی ورڅخه پاتې نه شي، بیا دې د هغه کونډه د کورنۍ څخه دباندې د بل چا سره واده نه شي. دا د مړه شوي سړي د ورور وظیفه ده چې د هغې سره واده وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_5.mp3', '', 1761754199, 1761754199),
(47195, 'Deuteronomy 25:6', 'Deuteronomy', 25, 6, 'د هغوی اول زوی چې پیدا شي، هغه به د مړ شوي سړي زوی ګڼل کیږي، ترڅو د هغه نوم د اسراییلو د قوم څخه ورک نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_6.mp3', '', 1761754199, 1761754199),
(47196, 'Deuteronomy 25:7', 'Deuteronomy', 25, 7, 'خو که چېرې د مړ شوي سړي ورور نه غواړي چې د هغې سره واده وکړي، نو هغه ښځه دې د ښار مشرانو ته چې د ښار په دروازه کې غونډه کوي، ورشي او داسې دې ورته ووایي: ‹زما لېور زما په حق کې خپل مسوولیت نه تر سره کوي، هغه د دې خبرې څخه انکار کوي چې د هغه ورور دې د اسراییلو په قوم کې اولاده ولري.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_7.mp3', '', 1761754199, 1761754199),
(47197, 'Deuteronomy 25:8', 'Deuteronomy', 25, 8, 'بیا دې د ښار مشران د هغې لېور راوغواړي او خبرې دې ورسره وکړي. که چېرې بیاهم د هغې سره د واده کولو څخه انکار کوي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_8.mp3', '', 1761754199, 1761754199),
(47198, 'Deuteronomy 25:9', 'Deuteronomy', 25, 9, 'نو د هغه د ورور کونډه دې د ښار د مشرانو په حضور کې هغه ته ورشي، د هغه یوه څپلۍ دې وباسي، په مخ دې ورته لیاړې تو کړي او داسې دې ووایي: ‹د هغه سړي سره چې نه غواړي د خپل مړ ورور کور یې ودان شي داسې کیږي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_9.mp3', '', 1761754199, 1761754199),
(47199, 'Deuteronomy 25:10', 'Deuteronomy', 25, 10, 'وروسته له دې به د هغه سړي کورنۍ په اسراییلو کې د څپلۍ ویستل شوي د کورنۍ په نوم مشهوره شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_10.mp3', '', 1761754199, 1761754199),
(47200, 'Deuteronomy 25:11', 'Deuteronomy', 25, 11, 'که چېرې دوه کسان یو د بل سره جنګ کوي او د یو سړي ښځه هڅه وکړي چې خپل مېړه د هغه سړي څخه وژغوري او هغه سړی د تناسلي الې څخه ونیسي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_11.mp3', '', 1761754199, 1761754199),
(47201, 'Deuteronomy 25:12', 'Deuteronomy', 25, 12, 'نو په هغې باندې هېڅ رحم مه کوئ. د هغې لاس پرې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_12.mp3', '', 1761754199, 1761754199),
(47202, 'Deuteronomy 25:15', 'Deuteronomy', 25, 15, 'د سمو وزنونو او اندازو څخه کار اخلئ، ترڅو تاسو په هغه خاوره کې چې خپل څښتن خدای یې درکوي زیات عمر ولرئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_15.mp3', '', 1761754199, 1761754199),
(47203, 'Deuteronomy 25:16', 'Deuteronomy', 25, 16, 'څښتن د داسې خلکو څخه چې ټګي او منافقت کوي، کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_16.mp3', '', 1761754199, 1761754199),
(47204, 'Deuteronomy 25:17', 'Deuteronomy', 25, 17, 'در په یاد کړئ کله چې تاسو د مصر څخه راتللئ، عمالیقیانو په تاسو باندې څه وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_17.mp3', '', 1761754199, 1761754199),
(47205, 'Deuteronomy 25:18', 'Deuteronomy', 25, 18, 'هغوی د خدای څخه هېڅ وېره نه درلودله، په داسې حال کې چې تاسو ډېر ستړي وئ، نو د شا له خوا یې درباندې حمله وکړه او هغه کسان چې شاته پاتې وو هغوی ټول یې ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_18.mp3', '', 1761754199, 1761754199),
(47206, 'Deuteronomy 25:19', 'Deuteronomy', 25, 19, 'نو بیا کله چې خپل څښتن خدای تاسو ته هغه وطن درکړي او د خپلو ټولو دښمنانو څخه مو چې ستاسو په شاوخوا کې اوسیږي خوندي وساتي، دا خبره هېره نه کړئ چې عمالیقیان باید په پوره توګه د ځمکې له مخ څخه ورک کړئ، ترڅو هېڅوک نور هغوی یاد نه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy25_verse_19.mp3', '', 1761754199, 1761754199),
(47207, 'Psalms 52:1', 'Psalms', 52, 1, 'ای زوروره، څه له فخر کړې په خپلو بدو؟ ده تلپاتې د خدای مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms52_verse_1.mp3', '', 1761754199, 1761754199),
(47208, 'Psalms 52:2', 'Psalms', 52, 2, 'ته پلانونه جوړوې چې کړې تباه نور خلک د ستا ژبه د چاړې په شان تېره ده ته همېش جوړوې دروغ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms52_verse_2.mp3', '', 1761754199, 1761754199),
(47209, 'Psalms 52:3', 'Psalms', 52, 3, 'له نېکۍ نه بدي زیاته خوښوې ته له رښتیا څخه دروغ ډېر خوښوې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms52_verse_3.mp3', '', 1761754199, 1761754199),
(47210, 'Psalms 52:4', 'Psalms', 52, 4, 'ای دروغجنه! دا خوښیږي د ستا چې په خبرو خپلو زیان خلکو ته ورسوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms52_verse_4.mp3', '', 1761754199, 1761754199);